import{_ as t,c as o,o as a,a5 as n}from"./chunks/framework.CUJoMJm2.js";const b=JSON.parse('{"title":"ADR 005: Transport ABI Package","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-transport-abi.md","filePath":"adr/005-transport-abi.md","lastUpdated":1768070912000}'),r={name:"adr/005-transport-abi.md"};function i(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/005-transport-abi.md for this page in Markdown format</div><h1 id="adr-005-transport-abi-package" tabindex="-1">ADR 005: Transport ABI Package <a class="header-anchor" href="#adr-005-transport-abi-package" aria-label="Permalink to “ADR 005: Transport ABI Package”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: Architecture</li><li><strong>Tags</strong>: architecture, transport</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The project architecture requires a <code>@sideband/transport</code> package as the ABI layer between protocol and concrete implementations. The initial architecture inadvertently mixed transport concerns into <code>@sideband/protocol</code> via a low-level callback-based <code>RawTransport</code> interface.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Created <code>@sideband/transport</code> as a dedicated, transport-agnostic ABI layer:</p><p><strong>Core interfaces:</strong></p><ul><li><code>Transport</code>: Entry point for <code>connect()</code> (client) and optional <code>listen()</code> (server)</li><li><code>TransportConnection</code>: Bidirectional channel with <code>send()</code>, <code>close()</code>, and <code>inbound: AsyncIterable&lt;Uint8Array&gt;</code></li><li><code>TransportEndpoint</code>: Branded string for connection targets (format is transport-specific)</li></ul><p><strong>Dependency rule:</strong></p><ul><li><code>@sideband/transport</code> depends only on <code>@sideband/protocol</code> (imports <code>ConnectionId</code>)</li><li>All concrete transports (<code>transport-browser</code>, <code>transport-node</code>) depend on <code>@sideband/transport</code></li><li><code>@sideband/runtime</code> depends on <code>@sideband/transport</code>, not on concrete implementations</li></ul><p><strong>Key constraint:</strong> No I/O, codec, or environment-specific logic. Transport is purely an interface contract.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><ul><li><strong>Layered isolation</strong>: Concrete transports depend on the ABI, not vice versa; enables swappable implementations</li><li><strong>Testability</strong>: MemoryTransport reference implementation serves as both documentation and test harness</li><li><strong>Async iterables</strong>: Inbound stream via <code>AsyncIterable&lt;Uint8Array&gt;</code> enables backpressure, composition, and natural error handling</li><li><strong>Stateless types</strong>: <code>TransportEndpoint</code> and <code>ConnectionId</code> are transport-agnostic, avoiding implicit coupling</li></ul>',14)])])}const h=t(r,[["render",i]]);export{b as __pageData,h as default};
